const g=msg.genesis;
if (!g || g.execution !== 'not-started' || !g.validation?.ok) {
  node.error('GENESIS R01 contract missing or invalid', msg); return null;
}
const r=g.region, layers=r.layers || [], projs=r.projections || [];
const pct=layers.reduce((s,l)=>s+Number(l.share||0),0);
const ids=new Set(layers.flatMap(l=>(l.populations||[]).map(p=>p.id)));
const missing=projs.filter(p=>[p.source,p.target].some(x=>!ids.has(x)&&!x.startsWith('dante.')));
if(Math.abs(pct-100)>1e-6 || missing.length || r.neurons.total!==1000000 || layers.length!==6 || projs.length!==12){
  node.error('GENESIS R01 invariant violated: layer shares/projections/virtual counts',msg);return null;
}
const shares=layers.map(l=>({id:l.id,percent:l.share,neurons:Math.floor(r.neurons.total*l.share/100),populations:l.populations?.length||0}));
msg.payload={event:'dante_neural_region_validated',region_id:r.id,mode:g.execution,region_neurons:r.neurons.total,active_budget:r.runtime.active_budget,virtual_address_limit:r.runtime.virtual_address_limit,layer_count:layers.length,population_count:layers.reduce((s,l)=>s+(l.populations?.length||0),0),projection_count:projs.length,layer_percent_total:pct,genome_source:r.genome?.source,allocated_layers:shares,graph_ir:{schema:g.graph_ir.schema,nodes:g.graph_ir.nodes.length,edges:g.graph_ir.edges.length},resource_lower_bound:g.resources,provenance:r.provenance};
node.status({fill:'green',shape:'dot',text:'V1 ✓ 6 layers / 12 projections'});
return msg;
